import{readFile,writeFile,mkdir}from'node:fs/promises';import{resolve}from'node:path';import{createRequire}from'node:module';import assert from'node:assert/strict';
const require=createRequire(resolve('晶晶日上工程交接包/01_源码/frontend_ops_workspace/package.json')),{chromium}=require('playwright-core'),cfg=JSON.parse(await readFile(process.argv[2],'utf8')),base=cfg.origin;
if(!base.startsWith('http://127.0.0.1:'))assert.equal(process.env.CLIENT_TEST_PUBLIC_ORIGIN,base);
const out=resolve('docs/testing/evidence/tonight-core-ui-20261104/page-extension/stock');await mkdir(out,{recursive:true});const results=[],records=[],errors=[],external=[];let failure;
const browser=await chromium.launch({executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',headless:true});
async function open(){const ctx=await browser.newContext({viewport:{width:430,height:1000},locale:'zh-CN',...(process.env.CLIENT_TEST_STORAGE_STATE?{storageState:process.env.CLIENT_TEST_STORAGE_STATE}:{})});await ctx.route('**/*',r=>{const u=r.request().url();if(new URL(u).origin===base||u.startsWith('blob:')||u.startsWith('data:'))return r.continue();external.push(u.split('?')[0]);return r.abort();});const p=await ctx.newPage();p.on('pageerror',e=>errors.push(e.message));await p.goto(base);await p.locator('#main').waitFor();const data=await(await ctx.request.get(base+'/__test/bootstrap')).json();const headers={Origin:base,Authorization:'Bearer '+data.bearer_token,'X-Acting-Party':data.party_id};async function api(route,body,account=false){const h={...headers,...body?{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()}:{} };if(account)delete h['X-Acting-Party'];const r=await ctx.request.fetch(base+route,{method:body?'POST':'GET',headers:h,...body?{data:body}:{}});const j=await r.json();assert.equal(r.status(),200,route+':'+JSON.stringify(j.error));return j.data;}
 async function go(route){const target='/app/?check='+Date.now()+'#'+route;await Promise.all([p.waitForEvent('framenavigated',f=>f.url()===base+target),p.locator('#app').evaluate((e,v)=>{e.src=v;},target)]);const f=p.locator('#app').contentFrame();await f.locator('flt-semantics-placeholder').waitFor({state:'attached',timeout:60000});await f.locator('flt-semantics-placeholder').evaluate(e=>e.click());await f.locator('flt-semantics').first().waitFor({timeout:60000});await p.waitForLoadState('networkidle');await p.waitForTimeout(600);return f;}
 return{p,ctx,api,go};}
async function press(p,l){for(let n=0;n<100;n++){if(!await l.count()){const box=await p.locator('#app').boundingBox();await p.mouse.move(box.x+box.width/2,Math.min(box.y+box.height-60,p.viewportSize().height-80));await p.mouse.wheel(0,420);await p.waitForTimeout(160);continue;}if(!await l.isEnabled({timeout:500}).catch(()=>false)){await p.waitForTimeout(200);continue;}const b=await l.boundingBox({timeout:250}).catch(()=>null),f=await p.locator('#app').boundingBox();if(b&&b.y+b.height/2>f.y+5&&b.y+b.height/2<Math.min(f.y+f.height,p.viewportSize().height-10)-5){await p.mouse.click(b.x+b.width/2,b.y+b.height/2);return;}await p.mouse.move(f.x+f.width/2,Math.min(f.y+f.height-30,p.viewportSize().height-80));await p.mouse.wheel(0,b&&b.y<f.y?-400:400);await p.waitForTimeout(80);}await p.screenshot({path:resolve(out,'control-failure.png')});await writeFile(resolve(out,'control-failure.txt'),await p.locator('#app').contentFrame().locator('body').innerText());throw Error('业务控件未进入可操作范围：'+l.toString());}

let session;
try{
 const {p,ctx,api,go}=session=await open();const writes=[];p.on('request',r=>{if(r.method()==='POST'&&r.url().includes('/api/v1/'))writes.push(new URL(r.url()).pathname)});
 const before=await api('/api/v1/stock/purchases');let f=await go('/stock/catalog');await writeFile(resolve(out,'01-catalog.txt'),await f.locator('body').innerText());await p.screenshot({path:resolve(out,'01-catalog.png')});
 await press(p,f.getByText(/查看详情与预览/).first());await p.waitForTimeout(600);await press(p,f.getByRole('checkbox',{name:/我已阅读本版价格/}));await press(p,f.getByRole('button',{name:'确认本版购买并查看原订单',exact:true}));
 const request=p.waitForResponse(r=>r.request().method()==='POST'&&r.url().endsWith('/stock/checkout'));await press(p,f.getByRole('button',{name:'确认办理',exact:true}));const response=await request,j=await response.json();assert(response.ok(),JSON.stringify(j.error));const order=j.data;assert.equal(order.current_status,'OPEN');assert(!before.items.some(x=>x.order_id===order.id));records.push({order_id:order.id,listing_id:order.data.quote.stock_video.listing_id,expected_minor:order.data.quote.total_minor});results.push('从目录实际选片、阅读许可并建立全新未付款订单');await p.waitForTimeout(700);await p.screenshot({path:resolve(out,'02-new-order.png')});
 await press(p,f.getByRole('button',{name:'进入收银台',exact:true}));await press(p,f.getByRole('checkbox',{name:/我已核对本次金额/}));await press(p,f.getByRole('button',{name:'建立本节点付款记录',exact:true}));await press(p,f.getByRole('button',{name:'确认办理',exact:true}));await p.locator('#simulationDialog').waitFor();await p.screenshot({path:resolve(out,'03-simulated-payment.png')});await p.getByRole('button',{name:'模拟成功',exact:true}).click();await p.waitForTimeout(1800);
 const paid=await api('/api/v1/trade/records/'+order.id);assert.equal(paid.current_status,'PAID');assert.equal(paid.data.financial.received_minor,order.data.quote.total_minor);records[0].received_minor=paid.data.financial.received_minor;results.push('同单从收银台选择模拟成功，服务器确认PAID且实收等于原单金额');await p.screenshot({path:resolve(out,'04-payment-result.png')});
 // Return to the same order with the normal App return-order button; no route fallback.
 await press(p,f.getByRole('button',{name:'返回订单',exact:true}));records[0].order_return='clicked normal return-order button';
 await press(p,f.getByRole('button',{name:'查看已购视频与许可',exact:true}));await p.waitForTimeout(500);const download= p.waitForEvent('download',{timeout:30000});await press(p,f.getByRole('button',{name:'下载本次私有文件',exact:true}));const d=await download;assert.equal(await d.failure(),null);const bytes=await readFile(await d.path());assert(bytes.length>1000);const {createHash}=await import('node:crypto');records[0].download_bytes=bytes.length;records[0].download_sha256=createHash('sha256').update(bytes).digest('hex');
 const owned=await api('/api/v1/stock/purchases/'+order.id);assert.equal(owned.order_id,order.id);assert.equal(owned.data.status,'ACTIVE');results.push('同一订单的本人已购许可生效，点击私有文件下载实际取得文件');await p.screenshot({path:resolve(out,'05-downloaded.png')});
 records[0].business_post_routes=writes;assert(writes.some(x=>x.endsWith('/stock/checkout'))&&writes.some(x=>x==='/api/v1/trade/payments'));
}catch(e){failure=e.stack;process.exitCode=1;if(session){await session.p.screenshot({path:resolve(out,'failure.png')}).catch(()=>{});await writeFile(resolve(out,'failure.txt'),await session.p.locator('#app').contentFrame().locator('body').innerText().catch(()=>''));}}
finally{await session?.ctx.close();await browser.close();await writeFile(resolve(out,'RESULTS.json'),JSON.stringify({at:new Date().toISOString(),version:cfg.version,scope:'New order through real App Web UI; all external payments simulated; GET-only independent verification',checks:results,records,failure,errors,external},null,2));console.log(JSON.stringify({checks:results,failure}));}
